-- FlowLogix: database schema and demo data
--
-- How to use:
--   1. Create an empty database (e.g. `flowlogix`, collation utf8mb4_unicode_ci).
--   2. Select it and import this file (phpMyAdmin > Import, or the mysql client).
--
-- Demo accounts (test data only): admin, manager, depozit, tura. Password: demo123
-- The demo orders are shifted at the end of the script so that the most recent
-- day of activity is the day you import the file.

SET NAMES utf8mb4;

DROP TABLE IF EXISTS `users`;
DROP TABLE IF EXISTS `inbound_orders`;
DROP TABLE IF EXISTS `pickpack_orders`;
DROP TABLE IF EXISTS `outbound_orders`;
DROP TABLE IF EXISTS `simulator_runs`;

CREATE TABLE `users` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `name` VARCHAR(100) NOT NULL,
  `password` VARCHAR(255) NOT NULL COMMENT 'bcrypt hash from password_hash()',
  `role` ENUM('tura','depozit','manager','admin') NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_users_name` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `inbound_orders` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `supplier_name` VARCHAR(150) NOT NULL,
  `reception_number` VARCHAR(50) NOT NULL,
  `status` ENUM('pending','processing','completed') NOT NULL,
  `priority` ENUM('low','medium','high') NOT NULL DEFAULT 'medium',
  `created_at` DATETIME NOT NULL,
  `finished_at` DATETIME DEFAULT NULL,
  `expected_finished_date` DATE DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_inbound_reception_number` (`reception_number`),
  KEY `idx_inbound_created_at` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `pickpack_orders` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `order_number` VARCHAR(50) NOT NULL,
  `operator_name` VARCHAR(100) NOT NULL,
  `items_count` INT NOT NULL,
  `status` ENUM('not_started','in_progress','completed') NOT NULL,
  `created_at` DATETIME NOT NULL,
  `finished_at` DATETIME DEFAULT NULL,
  `expected_finished_date` DATE DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_pickpack_order_number` (`order_number`),
  KEY `idx_pickpack_created_at` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `outbound_orders` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `order_number` VARCHAR(50) NOT NULL,
  `destination` VARCHAR(150) NOT NULL,
  `planned_date` DATETIME NOT NULL,
  `delay_minutes` INT DEFAULT 0,
  `status` ENUM('ready','shipped','delayed') NOT NULL,
  `created_at` DATETIME NOT NULL,
  `finished_at` DATETIME DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_outbound_order_number` (`order_number`),
  KEY `idx_outbound_created_at` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- One row per simulated hour (jobs/simulate_orders.php). The primary key
-- guarantees that the same hour is never simulated twice.
CREATE TABLE `simulator_runs` (
  `run_hour` DATETIME NOT NULL,
  `created_orders` INT NOT NULL,
  `advanced_orders` INT NOT NULL,
  `ran_at` DATETIME NOT NULL,
  PRIMARY KEY (`run_hour`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Summaries written by jobs/daily_summary.php (Claude Haiku). Not dropped above:
-- they survive the nightly reload of the demo data, so the dashboard keeps the latest one.
CREATE TABLE IF NOT EXISTS `daily_summaries` (
  `id` INT NOT NULL AUTO_INCREMENT,
  `generated_at` DATETIME NOT NULL,
  `summary` TEXT NOT NULL,
  `model` VARCHAR(50) NOT NULL,
  `input_tokens` INT NOT NULL,
  `output_tokens` INT NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_summaries_generated_at` (`generated_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

