-- 515 demo rows

-- Move all demo dates forward so the latest day of activity is today.
-- Rows are updated newest first, so a shifted reception number never
-- collides with one that has not been shifted yet.
SET @shift = (
  SELECT DATEDIFF(CURDATE(), DATE(MAX(last_day))) FROM (
    SELECT MAX(created_at) AS last_day FROM inbound_orders
    UNION ALL SELECT MAX(created_at) FROM pickpack_orders
    UNION ALL SELECT MAX(created_at) FROM outbound_orders
  ) AS t
);

UPDATE inbound_orders
SET created_at             = created_at + INTERVAL @shift DAY,
    finished_at            = finished_at + INTERVAL @shift DAY,
    expected_finished_date = expected_finished_date + INTERVAL @shift DAY,
    reception_number = IF(reception_number LIKE 'DEMO-%',
        CONCAT('DEMO-',
               DATE_FORMAT(STR_TO_DATE(SUBSTRING(reception_number, 6, 10), '%Y-%m-%d') + INTERVAL @shift DAY, '%Y-%m-%d'),
               SUBSTRING(reception_number, 16)),
        reception_number)
ORDER BY created_at DESC;

UPDATE pickpack_orders
SET created_at             = created_at + INTERVAL @shift DAY,
    finished_at            = finished_at + INTERVAL @shift DAY,
    expected_finished_date = expected_finished_date + INTERVAL @shift DAY;

UPDATE outbound_orders
SET created_at   = created_at + INTERVAL @shift DAY,
    finished_at  = finished_at + INTERVAL @shift DAY,
    planned_date = planned_date + INTERVAL @shift DAY;
